+        let out: Result<Option<u64>, BoxErr> = retry_rpc_opt("get block", move || {
+            let a = a.clone();
+            async move {
+                a.record();
+                Ok(None)
+            }
+        })
+        .await;
+
+        assert_eq!(out.expect("a persistent null is not a transport error"), None);
+        assert_eq!(attempts.count(), RPC_MAX_ATTEMPTS);
+        assert_eq!(Instant::now() - start, Duration::from_secs(5 + 15 + 45));
+    }
+
+    #[tokio::test(start_paused = true)]
+    async fn retry_rpc_opt_recovers_from_a_mix_of_errors_and_nulls() {
+        let attempts = Arc::new(Attempts::default());
+        let a = attempts.clone();
+
+        let out: Result<Option<u64>, BoxErr> = retry_rpc_opt("get block", move || {
+            let a = a.clone();
+            async move {
+                match a.record() {
+                    0 => Err("error sending request: connection refused".into()),
+                    1 => Ok(None),
+                    _ => Ok(Some(5)),
+                }
+            }
+        })
+        .await;
+
+        assert_eq!(out.expect("no transport error"), Some(5));
+        assert_eq!(attempts.count(), 3);
+    }
+
+    #[tokio::test(start_paused = true)]
+    async fn retry_rpc_opt_propagates_the_final_error_string_verbatim() {
+        let out: Result<Option<u64>, BoxErr> =
+            retry_rpc_opt("sentinel call", || async { Err("EpochNotFinalized".into()) }).await;
+
+        assert_eq!(out.expect_err("every attempt failed").to_string(), "EpochNotFinalized");
+    }
+}
