//! In-process fault-injection transport, for exercising RPC failure modes without a node.
//!
//! The retry/failover layer is the bot's only defence against a lagging, lying or
//! rate-limiting endpoint, and every one of those conditions is impractical to produce
//! against a real anvil devnet. This module implements a [`tower::Service`] with the same
//! shape alloy's real HTTP transport has (`Service<RequestPacket, Response = ResponsePacket,
//! Error = TransportError, Future = TransportFut<'static>>`), so a `DynProvider` can be built
//! on top of it and driven through the production code paths unmodified.
//!
//! A near-identical copy lives in `tests/fake_rpc/mod.rs` for the integration tests; the
//! duplication is deliberate, so that `tests/` never depends on `#[cfg(test)]` internals of
//! the library and no test-only plumbing leaks into the crate's public API.

#![allow(dead_code)]

use alloy::network::Ethereum;
use alloy::primitives::{Address, B256, U256};
use alloy::providers::{DynProvider, ProviderBuilder};
use alloy::rpc::client::RpcClient;
use alloy::rpc::json_rpc::{
    ErrorPayload, RequestPacket, Response, ResponsePacket, ResponsePayload, SerializedRequest,
};
use alloy::transports::{TransportError, TransportErrorKind, TransportFut};
use std::borrow::Cow;
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll};
use tower::Service;

/// One JSON-RPC request as seen by the fake endpoint.
#[derive(Clone, Debug)]
pub struct Call {
    /// 0-based index over every request this transport has served.
    pub index: usize,
    /// 0-based index over requests for this same method only. Makes "fail the first two
    /// `eth_getBlockByNumber` calls" scriptable without the test tracking counters itself.
    pub method_index: usize,
    pub method: String,
    pub params: serde_json::Value,
}

impl Call {
    /// First positional parameter, or `Null`. Most eth_ methods this bot issues are
    /// dispatched on it (a block tag, or the call object).
    pub fn param(&self, i: usize) -> &serde_json::Value {
        self.params.get(i).unwrap_or(&serde_json::Value::Null)
    }

    /// Calldata of an `eth_call`, lowercased hex with `0x` prefix, or `""`.
    pub fn calldata(&self) -> String {
        self.param(0)
            .get("data")
            .or_else(|| self.param(0).get("input"))
            .and_then(|d| d.as_str())
            .unwrap_or("")
            .to_ascii_lowercase()
    }

    /// True when this is an `eth_call` whose 4-byte selector matches `selector`.
    pub fn selector_is(&self, selector: [u8; 4]) -> bool {
        self.method == "eth_call"
            && self
                .calldata()
                .starts_with(&alloy::primitives::hex::encode_prefixed(selector))
    }
}

/// What the fake endpoint does with one request.
#[derive(Debug)]
pub enum Fault {
    /// A JSON-RPC success carrying this `result`. Use [`Fault::null`] for the
    /// `"result": null` a mid-sync node returns for a block that does exist.
    Ok(serde_json::Value),
    /// A JSON-RPC *error object* delivered over an otherwise successful HTTP 200 - the case
    /// alloy's `FallbackLayer` does not score down on its own (see `ErrorAwareTransport`).
    RpcError { code: i64, message: String },
    /// A transport-level failure: connection refused, HTTP 5xx, HTTP 429.
    Transport(TransportError),
    /// A future that never resolves. Models an endpoint that accepted the connection and
    /// then went away; the real transport has a 30s reqwest timeout, the fake has none, so
    /// a test pairs this with `tokio::time::timeout` under a paused clock.
    Hang,
}

impl Fault {
    /// `"result": null`, as returned by a node that is behind the block it was asked for.
    pub fn null() -> Self {
        Self::Ok(serde_json::Value::Null)
    }

    /// HTTP 429. alloy classifies this as retryable (`HttpError::is_rate_limit_err`).
    pub fn rate_limited() -> Self {
        Self::Transport(TransportErrorKind::http_error(
            429,
            "rate limit exceeded".to_string(),
        ))
    }

    /// Connection-level failure, as if the endpoint were down.
    pub fn unreachable() -> Self {
        Self::Transport(TransportErrorKind::custom_str(
            "error sending request: connection refused",
        ))
    }
}

/// A scriptable, in-process alloy transport.
///
/// Cheap to clone; clones share the script and the call log, because alloy clones the
/// transport internally when building the client.
#[derive(Clone)]
pub struct FaultTransport {
    script: Arc<dyn Fn(&Call) -> Fault + Send + Sync>,
    log: Arc<Mutex<Vec<String>>>,
}

impl FaultTransport {
    pub fn new<F>(script: F) -> Self
    where
        F: Fn(&Call) -> Fault + Send + Sync + 'static,
    {
        Self {
            script: Arc::new(script),
            log: Arc::new(Mutex::new(Vec::new())),
        }
    }

    /// A `DynProvider` speaking to this fake endpoint, built the same way `config.rs`
    /// builds the real single-URL provider.
    pub fn provider(&self) -> DynProvider<Ethereum> {
        let client = RpcClient::builder().transport(self.clone(), false);
        DynProvider::new(ProviderBuilder::new().connect_client(client))
    }

    /// Total requests served, including the ones that failed.
    pub fn call_count(&self) -> usize {
        self.methods().len()
    }

    /// Requests served for one method.
    pub fn count_of(&self, method: &str) -> usize {
        self.methods().iter().filter(|m| *m == method).count()
    }

    /// Method names in the order they were received.
    pub fn methods(&self) -> Vec<String> {
        match self.log.lock() {
            Ok(log) => log.clone(),
            // A poisoned log means some other test thread panicked; surface the data anyway
            // rather than turning it into a second, confusing panic.
            Err(poisoned) => poisoned.into_inner().clone(),
        }
    }

    fn record(&self, method: &str, params: serde_json::Value) -> Call {
        // The guard is taken, used and dropped without crossing an await, matching the
        // convention the stores in `tasks/mod.rs` follow for `std::sync::Mutex`.
        let mut log = match self.log.lock() {
            Ok(log) => log,
            Err(poisoned) => poisoned.into_inner(),
        };
        let index = log.len();
        let method_index = log.iter().filter(|m| m.as_str() == method).count();
        log.push(method.to_string());
        drop(log);

        Call {
            index,
            method_index,
            method: method.to_string(),
            params,
        }
    }
}

impl Service<RequestPacket> for FaultTransport {
    type Response = ResponsePacket;
    type Error = TransportError;
    type Future = TransportFut<'static>;

    fn poll_ready(&mut self, _cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        Poll::Ready(Ok(()))
    }

    fn call(&mut self, req: RequestPacket) -> Self::Future {
        let is_batch = matches!(req, RequestPacket::Batch(_));
        let requests: Vec<SerializedRequest> = match req {
            RequestPacket::Single(r) => vec![r],
            RequestPacket::Batch(rs) => rs,
        };

        let mut replies = Vec::with_capacity(requests.len());
        for r in &requests {
            let params = r
                .params()
                .and_then(|p| serde_json::from_str(p.get()).ok())
                .unwrap_or(serde_json::Value::Null);
            let call = self.record(r.method(), params);

            let payload = match (self.script)(&call) {
                // A hang or a transport error takes down the whole packet, which is what a
                // real HTTP transport does too.
                Fault::Hang => return Box::pin(std::future::pending()),
                Fault::Transport(e) => return Box::pin(async move { Err(e) }),
                Fault::Ok(v) => ResponsePayload::Success(
                    serde_json::value::to_raw_value(&v)
                        .expect("fault script returned non-serializable JSON"),
                ),
                Fault::RpcError { code, message } => ResponsePayload::Failure(ErrorPayload {
                    code,
                    message: Cow::Owned(message),
                    data: None,
                }),
            };
            replies.push(Response {
                id: r.id().clone(),
                payload,
            });
        }

        let packet = if is_batch {
            ResponsePacket::Batch(replies)
        } else {
            match replies.pop() {
                Some(reply) => ResponsePacket::Single(reply),
                None => return Box::pin(async { Err(TransportErrorKind::custom_str("empty request packet")) }),
            }
        };
        Box::pin(async move { Ok(packet) })
    }
}

/// JSON body of an `eth_getBlockByNumber` reply carrying the given number and timestamp.
///
/// Every other header field is left at its default: nothing in this crate's block handling
/// reads them, and a test that starts depending on one should set it explicitly.
pub fn block(number: u64, timestamp: u64) -> serde_json::Value {
    let mut b = alloy::rpc::types::Block::default();
    b.header.hash = B256::from(U256::from(number));
    b.header.inner.number = number;
    b.header.inner.timestamp = timestamp;
    serde_json::to_value(&b).expect("block is serializable")
}

/// ABI-encoded return data for a call returning one 32-byte word (`uint256`, `uint64`, ...).
pub fn word(value: u64) -> serde_json::Value {
    serde_json::Value::String(alloy::primitives::hex::encode_prefixed(B256::from(
        U256::from(value),
    )))
}

/// ABI-encoded return data for a call returning an `address`.
pub fn address_word(addr: Address) -> serde_json::Value {
    serde_json::Value::String(alloy::primitives::hex::encode_prefixed(
        addr.into_word(),
    ))
}

