97	/// How far back to sample when measuring average block time. On chains shorter
98	/// than this the lookback is clamped to genesis and the divisor follows the
99	/// actual block delta, so the average stays correct instead of being skewed.
100	const BLOCK_TIME_SAMPLE_BLOCKS: u64 = 10_000;
101	
102	async fn get_avg_block_time_ms(provider: &DynProvider<Ethereum>) -> u64 {
103	    let latest_block = crate::retry_rpc_opt("get latest block", || async { provider.get_block_by_number(Default::default()).await }).await
104	        .unwrap_or_else(|e| panic!("Failed to get latest block: {e}"))
105	        .expect("Latest block not found");
106	    let latest = latest_block.header.number;
107	    let old = latest.saturating_sub(BLOCK_TIME_SAMPLE_BLOCKS);
108	    let old_block = crate::retry_rpc_opt("get old block", || async { provider.get_block_by_number(old.into()).await }).await
109	        .unwrap_or_else(|e| panic!("Failed to get old block: {e}"))
110	        .expect("Old block not found");
111	
112	    // `.max(1)` guards a genesis-only chain (latest == 0), where the delta is zero.
113	    let block_delta = latest.saturating_sub(old).max(1);
114	    let time_diff = latest_block.header.timestamp.saturating_sub(old_block.header.timestamp);
115	    (time_diff * 1000) / block_delta
116	}
