2	use alloy::providers::ProviderBuilder;
3	use alloy::primitives::Address;
4	use vea_validator::config::Route;
5	use vea_validator::contracts::IVeaInboxArbToEth;
6	use std::str::FromStr;
7	
8	const SNAPSHOT_FILE: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/.devnet-snapshot");
9	
10	pub async fn send_messages(route: &Route) {
11	    let inbox = IVeaInboxArbToEth::new(route.inbox_address, route.inbox_provider.clone());
12	    for i in 0..3u8 {
13	        let msg = alloy::primitives::Bytes::from(vec![0xDE, 0xAD, i]);
14	        inbox.sendMessage(Address::from_str("0x0000000000000000000000000000000000000001").unwrap(), msg)
15	            .send().await.unwrap().get_receipt().await.unwrap();
16	    }
17	}
18	
19	pub async fn restore_pristine() {
20	    let snapshot_id = std::fs::read_to_string(SNAPSHOT_FILE)
21	        .unwrap_or_else(|_| panic!("Missing {}. Run full-devnet.sh first.", SNAPSHOT_FILE));
22	    let snapshot_id = snapshot_id.trim();
23	
24	    let arb = ProviderBuilder::new().connect_http("http://localhost:8545".parse().unwrap());
25	    let eth = ProviderBuilder::new().connect_http("http://localhost:8546".parse().unwrap());
26	    let gnosis = ProviderBuilder::new().connect_http("http://localhost:8547".parse().unwrap());
27	
28	    let _: serde_json::Value = arb.raw_request("evm_revert".into(), vec![serde_json::json!(snapshot_id)]).await.unwrap();
29	    let _: serde_json::Value = eth.raw_request("evm_revert".into(), vec![serde_json::json!(snapshot_id)]).await.unwrap();
30	    let _: serde_json::Value = gnosis.raw_request("evm_revert".into(), vec![serde_json::json!(snapshot_id)]).await.unwrap();
31	
32	    let new_id: serde_json::Value = arb.raw_request("evm_snapshot".into(), Vec::<serde_json::Value>::new()).await.unwrap();
33	    let _: serde_json::Value = eth.raw_request("evm_snapshot".into(), Vec::<serde_json::Value>::new()).await.unwrap();
34	    let _: serde_json::Value = gnosis.raw_request("evm_snapshot".into(), Vec::<serde_json::Value>::new()).await.unwrap();
35	
36	    std::fs::write(SNAPSHOT_FILE, new_id.as_str().unwrap()).unwrap();
37	}
38	
39	pub async fn advance_past_epoch(outbox_provider: &impl Provider, epoch: u64, epoch_period: u64) {
40	    let ts = outbox_provider
41	        .get_block_by_number(Default::default()).await.unwrap().unwrap()
42	        .header.timestamp;
43	    let target = (epoch + 1) * epoch_period + 10;
44	    advance_time(target - ts).await;
45	}
46	
47	/// Mine `count` blocks (1s apart) on every devnet chain.
48	///
49	/// Anvil derives the `finalized` tag from the head block number, so a test that needs a
50	/// transaction to be visible at `finalized` has to produce blocks, not just advance the
51	/// clock - `advance_time` only ever mines one.
